derivationSteps=["δ(q0,0)=(q1,X,R); δ(q0,Y)=(q3,Y,R)","δ(q1,0)=(q1,0,R); δ(q1,Y)=(q1,Y,R); δ(q1,1)=(q2,Y,L)","δ(q2,0)=(q2,0,L); δ(q2,Y)=(q2,Y,L); δ(q2,X)=(q0,X,R)","δ(q3,Y)=(q3,Y,R); δ(q3,B)=(q4,B,R)  (q4 final)","Trace 0011: q0 0011 → X q1 011 → X0 q1 11 → X q2 0Y1 → q2 X0Y1 → X q0 0Y1 → XX q1 Y1 → XXY q1 1 → XX q2 YY → X q2 XYY → XX q0 YY → XXY q3 Y → XXYY q3 B → accept."],
diagram="…[B][0][0][1][1][B]…\n          ↑ head\n   Finite control (state q)",
examples=["{0ⁿ1ⁿ}","Binary increment"],
counterexamples=["A machine with δ undefined on some (q,a) simply halts (rejects) there."],
